        if (tagNameButtonAddToCart2.size() >= 2) {
            WebElement secondElementTagNameButtonAddToCart2 = tagNameButtonAddToCart2.get(1);
            System.out.println(secondElementTagNameButtonAddToCart2.getText());
        }
        boolean isPresentElementButtonAddToCart2 = !tagNameButtonAddToCart2.isEmpty();
        System.out.println("4) Поиск второй кнопки 'AddToCart' по наименованию тега 'Button' выполнен. Элемент присутствует на странице: " + isPresentElementButtonAddToCart2);
