        boolean isPresentElementDivContainingSpanClassSelectContainer = !divContainingSpanClassSelectContainer.isEmpty();
        System.out.println("15) Поиск крайнего элемента div в DOM, содержащего тег span имеющего класс 'select_container' через Xpath preceding выполнен. Элемент присутствует на странице: " + isPresentElementDivContainingSpanClassSelectContainer);
